using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace MacroExecute
{
    internal static class UsabilityTests
    {
        private static IEnumerable<Control> All(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in All(child))yield return nested;}}
        private static void Check(bool value,string message){if(!value)throw new Exception(message);}
        private static void Click(Button button){typeof(Button).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(button,new object[]{EventArgs.Empty});}
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Step summaries expose inverted images wait limits search area and random ranges",delegate{var image=new Step{Kind=ActionKind.IfImage,Negate=true,ImageData="synthetic",SearchIn=SearchArea.Rectangle,Width=80,Height=40,WaitForMatch=true,TimeoutMs=2500};Check(StepPresentation.Name(image).Contains("NOT found")&&StepPresentation.Summary(image).Contains("80×40")&&StepPresentation.Summary(image).Contains("2.5 s"),"Important image options hidden.");image.WaitForever=true;Check(StepPresentation.Summary(image).Contains("wait until Stop"),"Infinite wait hidden.");Check(StepPresentation.Summary(new Step{Kind=ActionKind.Delay,DelayMs=500,DelayMaxMs=1500}).Contains("500 ms – 1.5 s"),"Delay range hidden.");Check(StepPresentation.Summary(new Step{Kind=ActionKind.Repeat,Count=2,CountMax=5}).Contains("2 – 5"),"Repeat range hidden.");});
            test("Step finder searches all words disabled rows and content without filtering structure",delegate{var macro=Samples.Nested();macro.Steps[5].Enabled=false;Check(StepPresentation.Find(macro.Steps,"image missing").SequenceEqual(new[]{5,9}),"Content search wrong.");Check(StepPresentation.Find(macro.Steps,"disabled").SequenceEqual(new[]{5}),"Disabled rows cannot be found.");Check(StepPresentation.Find(macro.Steps,"  ").Length==0,"Empty search matches everything.");});
            test("Find navigation wraps in both directions and leaves document and history unchanged",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"find-navigation.png"));string original=Storage.Encode(form.DocumentHeadless());var list=All(form).OfType<MacroListView>().Single();form.FindHeadless("image missing",0);Check(list.SelectedIndices[0]==5,"First match not selected.");form.FindHeadless("image missing",1);Check(list.SelectedIndices[0]==9,"Next match wrong.");form.FindHeadless("image missing",1);Check(list.SelectedIndices[0]==5,"Forward search does not wrap.");form.FindHeadless("image missing",-1);Check(list.SelectedIndices[0]==9,"Backward search does not wrap.");form.FindHeadless("no-such-step-xxx",0);Check(All(form).OfType<Label>().Any(l=>l.Text=="No matches")&&list.Items.Count==11,"Search removed rows or has no empty-result feedback.");Click(All(form).OfType<Button>().First(b=>b.AccessibleName=="Close step search"));Check(Storage.Encode(form.DocumentHeadless())==original&&!All(form).OfType<Button>().First(b=>b.Text=="↶ Undo").Enabled&&!form.Visible,"Search edits data or creates history.");}});
            test("Selected block highlights its exact nested scope without adding columns",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"block-scope.png"));form.SelectHeadlessStep(2);var list=All(form).OfType<MacroListView>().Single();Check(list.Columns.Count==3&&list.Items.Cast<ListViewItem>().Where(i=>((StepRow)i.Tag).InSelectedBlock).Select(i=>i.Index).SequenceEqual(new[]{3,4,5,6}),"Scope highlight wrong.");Check(All(form).OfType<Label>().Any(l=>l.Text.Contains("5-row block")),"Inspector does not describe block scope.");form.SelectHeadlessStep(1);Check(list.Items.Cast<ListViewItem>().All(i=>!((StepRow)i.Tag).InSelectedBlock),"Old block highlight retained.");}});
            test("Partial playback availability rejects unfinished tails but retains single-step trial",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"range-guidance.png"));form.SelectHeadlessStep(1);Check(!All(form).OfType<Button>().First(b=>b.AccessibleName=="▶ From selected").Enabled&&All(form).OfType<Button>().First(b=>b.AccessibleName=="▶ Selected block").Enabled,"Unbalanced tail appears runnable.");form.SelectHeadlessStep(0);Check(All(form).OfType<Button>().First(b=>b.AccessibleName=="▶ From selected").Enabled,"Complete workflow tail disabled.");}});
            test("Transport labels describe finish pause and resume states",delegate{Check(TransportLabels.Play(false,false,false)=="▶ Play"&&TransportLabels.Play(true,false,false)=="Ⅱ Pause"&&TransportLabels.Play(true,false,true)=="▶ Resume","Playback action labels wrong.");Check(TransportLabels.Record(true)=="■ Finish"&&TransportLabels.Pause(true)=="▶ Resume","Recording/pause labels misleading.");});
            test("Runner Pause step publishes pause and resume without any desktop input",delegate{var host=new FakeHost();var runner=new Runner(host);var events=new List<bool>();runner.PauseChanged+=delegate(bool paused){events.Add(paused);if(paused)runner.Paused=false;};runner.Run(Plan.Build(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Pause},new Step{Kind=ActionKind.Note}}},directory),1,1,CancellationToken.None).GetAwaiter().GetResult();Check(events.SequenceEqual(new[]{true,false})&&host.Released,"Pause/resume notification failed.");});
            test("New macro navigation shortcuts preserve existing customized keys",delegate{var old=Shortcuts.Defaults().Where(s=>(int)s.Command<20).ToArray();old.First(s=>s.Command==AppCommand.Save).Key=(int)Keys.F3;old.First(s=>s.Command==AppCommand.Save).Modifiers=0;var normalized=Shortcuts.Normalize(old);Shortcuts.Validate(normalized,null);Check(normalized.First(s=>s.Command==AppCommand.NextMatch).Key==0&&normalized.First(s=>s.Command==AppCommand.Save).Chord==Keys.F3,"New shortcut took an existing binding.");});
            test("Undo back to the original document clears the unsaved-change marker",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"history-state.png"));form.AddHeadless(ActionKind.Note);Check(All(form).OfType<Label>().Any(l=>l.Text=="● Unsaved changes"),"Edit not marked dirty.");Click(All(form).OfType<Button>().First(b=>b.Text=="↶ Undo"));Check(!All(form).OfType<Label>().Any(l=>l.Text=="● Unsaved changes"),"Exact undo still claims changed document.");}});
            test("Compact step finder keeps navigation usable and row indexes stable",delegate{using(var form=new MainForm(Samples.Nested(),null,false,false,true)){form.Size=new Size(1000,650);HeadlessUi.Render(form,Path.Combine(directory,"find-compact.png"));form.FindHeadless("image missing",0);HeadlessUi.Render(form,Path.Combine(directory,"find-compact.png"),true);var list=All(form).OfType<MacroListView>().Single();Check(list.Items.Count==11&&list.SelectedIndices[0]==5,"Compact search changed indexes.");foreach(var button in All(form).OfType<Button>().Where(b=>b.AccessibleName=="Previous matching step"||b.AccessibleName=="Next matching step"||b.AccessibleName=="Close step search"))Check(button.Bottom<=button.Parent.ClientSize.Height&&button.Right<=button.Parent.ClientSize.Width,"Find navigation clips in a small window.");Check(!form.Visible,"Finder activated the desktop.");}});
            test("Guided editor gives fields useful accessible names",delegate{UiTheme.Style="Aftershock";using(var editor=new StepEditor(new Step{Kind=ActionKind.Delay},directory)){Check(All(editor).OfType<NumericUpDown>().Any(n=>!string.IsNullOrWhiteSpace(n.AccessibleName))&&!editor.Visible,"Editor fields remain unnamed.");}});
        }
    }
}
